 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    first = grid[0]
    # Infer the shortest cyclic color sequence from the unoccluded portions
    # of the first row.
    period = None
    for p in range(2, min(10, w + 1)):
        if all(value == 0 or value == first[c % p]
               for c, value in enumerate(first)):
            period = p
            break
    if period is None:
        raise ValueError('could not infer first-row cycle')
    cycle = first[:period]
    if any(value == 0 for value in cycle):
        # Find a fully visible cycle window elsewhere in the first row.
        for start in range(w - period + 1):
            window = first[start:start + period]
            if all(window):
                cycle = [None] * period
                for k, value in enumerate(window):
                    cycle[(start + k) % period] = value
                break
        if any(value is None for value in cycle):
            raise ValueError('incomplete color cycle')
    return [[cycle[(c + (1 if c < r else 0)) % period]
             for c in range(w)] for r in range(h)]
